PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS survey_sessions(id INTEGER PRIMARY KEY, source TEXT NOT NULL DEFAULT 'wigle_csv', label TEXT NOT NULL, started_at TEXT, ended_at TEXT, observation_count INTEGER NOT NULL DEFAULT 0, valid_count INTEGER NOT NULL DEFAULT 0, invalid_count INTEGER NOT NULL DEFAULT 0, duplicate_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS import_jobs(id INTEGER PRIMARY KEY, filename TEXT NOT NULL, status TEXT NOT NULL, bytes INTEGER NOT NULL DEFAULT 0, rows_seen INTEGER NOT NULL DEFAULT 0, rows_imported INTEGER NOT NULL DEFAULT 0, rows_invalid INTEGER NOT NULL DEFAULT 0, rows_duplicate INTEGER NOT NULL DEFAULT 0, error TEXT, survey_session_id INTEGER REFERENCES survey_sessions(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE IF NOT EXISTS wifi_observations(id INTEGER PRIMARY KEY, survey_session_id INTEGER NOT NULL REFERENCES survey_sessions(id) ON DELETE CASCADE, observed_at TEXT, bssid TEXT NOT NULL, ssid TEXT, auth_mode TEXT, channel INTEGER, frequency_mhz INTEGER, rssi INTEGER, latitude REAL, longitude REAL, altitude_m REAL, accuracy_m REAL, network_type TEXT NOT NULL DEFAULT 'WIFI', source_row_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(survey_session_id, source_row_hash));
CREATE INDEX IF NOT EXISTS idx_wifi_area ON wifi_observations(latitude,longitude);
CREATE TABLE IF NOT EXISTS canvassing_sessions(id INTEGER PRIMARY KEY, name TEXT NOT NULL, neighborhood TEXT NOT NULL, started_at TEXT, ended_at TEXT, visits INTEGER NOT NULL DEFAULT 1, source TEXT NOT NULL DEFAULT 'manual', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS opt_in_leads(id INTEGER PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT, contact TEXT NOT NULL, address TEXT, provider TEXT, monthly_bill TEXT, preferred_contact TEXT NOT NULL, interested TEXT NOT NULL, consent INTEGER NOT NULL CHECK(consent=1), consent_version TEXT NOT NULL, neighborhood TEXT, canvassing_session_id INTEGER REFERENCES canvassing_sessions(id) ON DELETE SET NULL, source TEXT NOT NULL DEFAULT 'cardputer', follow_up_status TEXT NOT NULL DEFAULT 'new', follow_up_date TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS lead_events(id INTEGER PRIMARY KEY, lead_id INTEGER NOT NULL REFERENCES opt_in_leads(id) ON DELETE CASCADE, event_type TEXT NOT NULL, event_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, detail TEXT);
CREATE TABLE IF NOT EXISTS neighborhood_aggregates(area_key TEXT PRIMARY KEY, center_lat REAL, center_lon REAL, unique_access_points INTEGER NOT NULL, observation_count INTEGER NOT NULL, avg_rssi REAL, channel_congestion_json TEXT NOT NULL, survey_sessions INTEGER NOT NULL, canvassing_visits INTEGER NOT NULL DEFAULT 0, opt_in_leads INTEGER NOT NULL DEFAULT 0, last_calculated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS device_sync_jobs(id INTEGER PRIMARY KEY, device_id TEXT NOT NULL, session_id TEXT NOT NULL, status TEXT NOT NULL, payload_version TEXT NOT NULL, lead_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_users(username TEXT PRIMARY KEY, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
